import { test, expect } from '@playwright/test';

test.describe('Accessibility - ARIA Landmarks', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('Check if main landmark is present', async ({ page }) => {
    const mainLandmark = await page.getByRole('main');
    expect(await mainLandmark.count()).toBe(1);
  });

  test('Check if navigation landmark is present', async ({ page }) => {
    const navLandmark = await page.getByRole('navigation');
    expect(await navLandmark.count()).toBe(1);
  });
});
